/* 顶部样式 */
.fcircle_page .author-content.fcirclePage {
  height: 19rem;
  color: var(--anzhiyu-white);
  overflow: hidden;
  margin-top: 0px;
}
.fcircle_page {
  --fc-accent: #b95c95;
  --fc-accent-soft: #ffe7f7;
  --fc-accent-line: rgba(185, 92, 149, 0.28);
  --anzhiyu-shadow-main: 0 8px 24px rgba(185, 92, 149, 0.2);
  --style-border-hover: 1px solid var(--fc-accent);
  --anzhiyu-main: var(--fc-accent);
}
[data-theme="dark"] .fcircle_page {
  --fc-accent: #f1a6d5;
  --fc-accent-soft: #352338;
  --fc-accent-line: rgba(241, 166, 213, 0.3);
}
#web_bg ~ .page:has(.fcircle_page) {
  background-color: transparent;
}
[data-theme="dark"] #web_bg ~ .page:has(.fcircle_page) {
  background-color: transparent;
}

#page:has(.fcircle_page) .page-title {
  display: none;
}

#page:has(.fcircle_page) {
  border: 0;
  box-shadow: none !important;
  padding: 0 !important;
  background: transparent !important;
