#page:has(#anMusic-page) {
  border: 0;
  box-shadow: none !important;
  padding: 0 !important;
  background: transparent !important;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}
/* 背景图就是当前封面，封面是任意的：亮封面会把整页的白字冲掉。用 darken 把
   封面的每个通道钳制在 #555 以下——暗封面几乎原样保留，亮封面自动压暗，所以
   白字在任何一张封面下都有足够对比度，不必再靠明暗主题去猜。 */
#an_music_bg {
  display: none;
  background-color: #555;
  background-blend-mode: darken;
  /* darken 是逐通道取最小值，会把高饱和的亮封面压成灰，saturate 补回一点色相 */
  filter: blur(63px) saturate(1.2);
  opacity: 0.6;
  position: fixed;
  z-index: -999;
  background-attachment: local;
  background-position: center center;
  background-size: cover;
  background-repeat: no-repeat;
  width: 200%;
  height: 200%;
  top: -50%;
  left: -50%;
  transform: rotate(0deg);
}
body:has(#anMusic-page) #an_music_bg {
  display: block;
}

/* 整个播放页只有一套配色：深色。页面上的文字全部压在封面背景上，深浅只能由封面
   决定，跟站点的明暗主题无关——所以浅色模式下也把主题变量固定成深色那一套，
   否则导航标题、搜索、下拉菜单和移动端歌单抽屉会是「深色字 + 浅色块」压在深色
   封面上。取值同 themes/butterfly/source/css/_mode/darkmode.styl 编译结果。
   color-scheme 让滚动条等原生控件在浅色主题下也跟着变深。 */
body:has(#anMusic-page) {
  --font-color: rgba(255, 255, 255, 0.7);
  --light-grey: rgba(255, 255, 255, 0.7);
  --dark-grey: rgba(255, 255, 255, 0.2);
  --white: rgba(255, 255, 255, 0.9);
  --text-highlight-color: rgba(255, 255, 255, 0.9);
  --text-bg-hover: #383838;
  --card-bg: #121212;
  --sidebar-bg: #121212;
