:root {
  --bubble-text-color: #e9a218;
  --bubble-text-hover-color: #2c7fe7;
  --bubble-text-shadow: rgba(35,35,35,0.5);
}
[data-theme="dark"] {
  --bubble-text-color: #f2b94b;
  --bubble-text-hover-color: #2c7fe7;
  --bubble-text-shadow: rgba(35,35,35,0.5);
}
.bubble-content {
  display: inline-block;
  color: var(--bubble-text-color);
  font-weight: bold;
  transition: all 0.2s ease-in-out;
  text-shadow: var(--bubble-text-shadow);
}
.bubble-content:hover {
  transition: all 0.2s ease-in-out;
  color: var(--bubble-text-hover-color);
}
.bubble-content:hover + .bubble-notation .bubble-item {
  transform: translate(-40px, 10px) rotateX(0deg);
  transition: all 0.5s ease-in-out;
  opacity: 1;
}
.bubble-notation {
  display: inline-block;
}
.bubble-item {
  transition: all 0.5s ease-in-out;
  opacity: 0;
  color: #fff;
  z-index: 99;
  display: flex;
  position: absolute;
  transform: translate(-40px, 10px) rotateX(90deg);
  width: auto;
  height: auto;
  max-width: 400px;
  overflow: hidden;
  padding: 20px 10px 10px 10px;
  clip-path: polygon(5px 10px, 20px 10px, 30px 0, 40px 10px, calc(100% - 5px) 10px, 100% 15px, 100% calc(100% - 5px), calc(100% - 5px) 100%, 5px 100%, 0 calc(100% - 5px), 0 15px, 5px 10px);
}
.carousel {
  touch-action: none;
  overflow: hidden;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  background: transparent;
  height: fit-content;
  min-height: 600px;
  -webkit-perspective: 1000px;
  perspective: 1000px;
  -webkit-transform-style: preserve-3d;
  transform-style: preserve-3d;
}
.drag-container,
.spin-container {
  position: relative;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  margin: auto;
  -webkit-transform-style: preserve-3d;
  transform-style: preserve-3d;
  -webkit-transform: rotateX(-10deg);
  transform: rotateX(-10deg);
}
.drag-container img,
.drag-container video {
  -webkit-transform-style: preserve-3d;
  transform-style: preserve-3d;
  position: absolute;
  left: 0;
  top: 0;
  object-fit: cover;
  height: 100%;
  width: 100%;
  line-height: 200px;
  font-size: 50px;
  text-align: center;
  -webkit-box-shadow: 0 0 8px #fff;
  box-shadow: 0 0 8px #fff;
  -webkit-box-reflect: below 10px linear-gradient(transparent, transparent, rgba(0,0,0,0.333));
}
.drag-container .img-alt.is-center {
  display: none;
}
.drag-container br {
  display: none;
}
.drag-container p {
  font-family: Serif;
  position: absolute;
  top: 100%;
  left: 50%;
  -webkit-transform: translate(-50%, -50%) rotateX(90deg);
  transform: translate(-50%, -50%) rotateX(90deg);
  color: #fff;
}
.drag-container img:hover,
.drag-container video:hover {
  -webkit-box-shadow: 0 0 15px rgba(255,255,255,0.867);
  box-shadow: 0 0 15px rgba(255,255,255,0.867);
  -webkit-box-reflect: below 10px linear-gradient(transparent, transparent, rgba(0,0,0,0.467));
}
.carousel-ground {
  width: 900px;
  height: 900px;
  position: absolute;
  top: 100%;
  left: 50%;
  -webkit-transform: translate(-50%, -50%) rotateX(90deg);
  transform: translate(-50%, -50%) rotateX(90deg);
  background: -webkit-radial-gradient(center center, farthest-side, rgba(153,153,153,0.2), transparent);
}
img.medium-zoom-image.entered.loaded.medium-zoom-image--opened {
  width: auto !important;
}
@-webkit-keyframes spin {
  from {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
  to {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
}
@-webkit-keyframes spinRevert {
  from {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
  to {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
}
@-moz-keyframes spin {
  from {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
  to {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
}
@-webkit-keyframes spin {
  from {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
  to {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
}
@-o-keyframes spin {
  from {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
  to {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
}
@keyframes spin {
  from {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
  to {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
}
@-moz-keyframes spinRevert {
  from {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
  to {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
}
@-webkit-keyframes spinRevert {
  from {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
  to {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
}
@-o-keyframes spinRevert {
  from {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
  to {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
}
@keyframes spinRevert {
  from {
    -webkit-transform: rotateY(360deg);
    transform: rotateY(360deg);
  }
  to {
    -webkit-transform: rotateY(0deg);
    transform: rotateY(0deg);
  }
}
.checkbox {
  display: flex;
  align-items: center;
}
.checkbox input {
  -webkit-appearance: none;
  -moz-appearance: none;
  -ms-appearance: none;
  -o-appearance: none;
  appearance: none;
  position: relative;
  height: 16px;
  width: 16px;
  transition: all 0.15s ease-out 0s;
  cursor: pointer;
  display: inline-block;
  outline: none;
  border-radius: 2px;
  flex-shrink: 0;
  margin-right: 8px;
  border: 2px solid #2196f3;
  pointer-events: none;
}
.checkbox input[type="checkbox"]:before {
  left: 1px;
  top: 5px;
  width: 0;
  height: 2px;
  transition: all 0.2s ease-in;
  transform: rotate(45deg);
  -webkit-transform: rotate(45deg);
  -moz-transform: rotate(45deg);
  -ms-transform: rotate(45deg);
  -o-transform: rotate(45deg);
}
.checkbox input[type="checkbox"]:after {
  right: 7px;
  bottom: 3px;
  width: 2px;
  height: 0;
  transition: all 0.2s ease-out;
  transform: rotate(40deg);
  -webkit-transform: rotate(40deg);
  -moz-transform: rotate(40deg);
  -ms-transform: rotate(40deg);
  -o-transform: rotate(40deg);
  transition-delay: 0.25s;
}
.checkbox input[type="checkbox"]:checked {
  background: #2196f3;
}
.checkbox input[type="checkbox"]:checked:before {
  left: 0;
  top: 7px;
  width: 6px;
  height: 2px;
}
.checkbox input[type="checkbox"]:checked:after {
  right: 3px;
  bottom: 1px;
  width: 2px;
  height: 10px;
}
.checkbox.minus input[type="checkbox"]:before {
  transform: rotate(0);
  left: 1px;
  top: 5px;
  width: 0;
  height: 2px;
}
.checkbox.minus input[type="checkbox"]:after {
  transform: rotate(0);
  left: 1px;
  top: 5px;
  width: 0;
  height: 2px;
}
.checkbox.minus input[type="checkbox"]:checked:before {
  left: 1px;
  top: 5px;
  width: 10px;
  height: 2px;
}
.checkbox.minus input[type="checkbox"]:checked:after {
  left: 1px;
  top: 5px;
  width: 10px;
  height: 2px;
}
.checkbox.plus input[type="checkbox"]:before {
  transform: rotate(0);
  left: 1px;
  top: 5px;
  width: 0;
  height: 2px;
}
.checkbox.plus input[type="checkbox"]:after {
  transform: rotate(0);
  left: 5px;
  top: 1px;
  width: 2px;
  height: 0;
}
.checkbox.plus input[type="checkbox"]:checked:before {
  left: 1px;
  top: 5px;
  width: 10px;
  height: 2px;
}
.checkbox.plus input[type="checkbox"]:checked:after {
  left: 5px;
  top: 1px;
  width: 2px;
  height: 10px;
}
.checkbox.times input[type="checkbox"]:before {
  transform: rotate(45deg);
  left: 3px;
  top: 1px;
  width: 0;
  height: 2px;
}
.checkbox.times input[type="checkbox"]:after {
  transform: rotate(135deg);
  right: 3px;
  top: 1px;
  width: 0;
  height: 2px;
}
.checkbox.times input[type="checkbox"]:checked:before {
  left: 1px;
  top: 5px;
  width: 10px;
  height: 2px;
}
.checkbox.times input[type="checkbox"]:checked:after {
  right: 1px;
  top: 5px;
  width: 10px;
  height: 2px;
}
.checkbox input[type="radio"] {
  border-radius: 50%;
}
.checkbox input[type="radio"]:before {
  content: "";
  display: block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin: 2px;
  transform: scale(0);
  transition: all 0.25s ease-out;
}
.checkbox input[type="radio"]:checked:before {
  transform: scale(1);
  background: var(--text-bg-hover);
}
.checkbox.red input {
  border-color: #fe5f58;
}
.checkbox.red input[type="checkbox"]:checked {
  background: #fe5f58;
}
.checkbox.red input[type="radio"]:checked:before {
  background: #fe5f58;
}
.checkbox.green input {
  border-color: #3dc550;
}
.checkbox.green input[type="checkbox"]:checked {
  background: #3dc550;
}
.checkbox.green input[type="radio"]:checked:before {
  background: #3dc550;
}
.checkbox.yellow input {
  border-color: #ffbd2b;
}
.checkbox.yellow input[type="checkbox"]:checked {
  background: #ffbd2b;
}
.checkbox.yellow input[type="radio"]:checked:before {
  background: #ffbd2b;
}
.checkbox.cyan input {
  border-color: #1bcdfc;
}
.checkbox.cyan input[type="checkbox"]:checked {
  background: #1bcdfc;
}
.checkbox.cyan input[type="radio"]:checked:before {
  background: #1bcdfc;
}
.checkbox.blue input {
  border-color: #2196f3;
}
.checkbox.blue input[type="checkbox"]:checked {
  background: #2196f3;
}
.checkbox.blue input[type="radio"]:checked:before {
  background: #2196f3;
}
.checkbox p {
  display: inline-block;
  margin-top: 2px !important;
  margin-bottom: 0 !important;
}
.checkbox input[type="checkbox"]:before,
.checkbox input[type="checkbox"]:after {
  position: absolute;
  content: "";
  background: #fff;
}
