div.videos {
  max-width: calc(100% + 2 * 4px);
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  align-items: flex-end;
  margin: 1em -4px;
}
div.videos .video,
div.videos iframe {
  width: 100%;
  margin: 4px;
}
div.videos iframe {
  border-radius: 4px;
  width: 100%;
  min-height: 300px;
}
div.videos.left {
  justify-content: flex-start;
}
div.videos.center {
  justify-content: center;
}
div.videos.right {
  justify-content: flex-end;
}
div.videos.stretch {
  align-items: stretch;
}
div.videos[col='1'] .video,
div.videos[col='1'] iframe {
  width: 100%;
}
div.videos[col='2'] .video,
div.videos[col='2'] iframe {
  width: calc(50% - 2 * 4px);
}
div.videos[col='3'] .video,
div.videos[col='3'] iframe {
  width: calc(33.33% - 2 * 4px);
}
div.videos[col='4'] .video,
div.videos[col='4'] iframe {
  width: calc(25% - 2 * 4px);
}
[data-theme="dark"] audio,
[data-theme="dark"] video {
  filter: brightness(0.7);
}
span.nota {
  color: #99a9bf;
  text-decoration: none;
  word-wrap: break-word;
  transition: all 0.2s;
  overflow-wrap: break-word;
}
span.nota:hover {
  color: var(--text-bg-hover);
}
span.nota:hover:before {
  position: fixed;
  width: fit-content;
  max-width: 80%;
  margin: auto;
  left: 0;
  right: 0;
  top: 10%;
  border-radius: 10px;
  text-align: center;
  z-index: 100;
  content: attr(data-nota);
  font-size: 16px;
  color: #fff;
  padding: 10px;
  background-color: var(--text-bg-hover);
}
[data-theme=dark] span.nota:hover:before {
  background-color: rgba(18,18,18,0.8);
}
@media (min-width: 1200px) {
  .poem {
    margin: 0 auto;
    height: auto;
    writing-mode: vertical-rl;
    writing-mode: tb-rl;
  }
  .poem p {
    text-decoration: underline;
    text-decoration-color: rgba(193,11,11,0.72);
    text-decoration-style: dashed;
  }
}
@font-face {
  font-family: 'Poem';
  src: url("https://unpkg.zhimg.com/akilar-candyassets/fonts/Poem.ttf");
  font-display: swap;
}
.poem p {
  font-family: 'Poem', 'KaiTi', sans-serif !important;
  font-size: 25px;
  text-align: center;
}
.poem-title {
  font-family: 'Poem', 'KaiTi', sans-serif !important;
  font-size: 2.5em;
  text-align: center;
}
.poem-author {
  text-align: center !important;
  font-family: 'Poem', 'KaiTi', sans-serif !important;
  font-size: 16px;
  color: #424242;
}
.progress {
  display: flex;
  font-size: var(--global-font-size);
  background-color: rgba(88,88,88,0.6);
  border-radius: 0.25rem;
  margin: 1rem 0;
  height: 2rem;
  overflow: hidden;
}
.progress p {
  margin: 0 0 0 10px !important;
}
.progress .progress-bar-animated {
  background-color: #a7b5fd !important;
  animation: progress-bar-stripes 1s linear infinite;
}
.progress .progress-bar-striped {
  background-image: linear-gradient(45deg, rgba(255,255,255,0.15) 25%, transparent 25%, transparent 50%, rgba(255,255,255,0.15) 50%, rgba(255,255,255,0.15) 75%, transparent 75%, transparent);
  background-size: 1rem 1rem;
}
.progress .progress-bar {
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: visible;
  color: #fff;
  text-align: center;
  white-space: nowrap;
  background-color: #0d6efd;
  transition: width 0.6s ease;
}
@media (prefers-reduced-motion: reduce) {
  .progress .progress-bar {
    transition: none;
  }
}
.progress .bg-green {
  background-color: #28a745 !important;
}
.progress .bg-yellow {
  background-color: #ffc107 !important;
}
.progress .bg-red {
  background-color: #dc3545 !important;
}
.progress .bg-cyan {
  background-color: #17a2b8 !important;
}
.progress .bg-blue {
  background-color: #0d6efd !important;
}
.progress .bg-gray {
  background-color: #7f838a !important;
}
@-moz-keyframes progress-bar-stripes {
  0% {
    background-position-x: 1rem;
  }
}
@-webkit-keyframes progress-bar-stripes {
  0% {
    background-position-x: 1rem;
  }
}
@-o-keyframes progress-bar-stripes {
  0% {
    background-position-x: 1rem;
  }
}
@keyframes progress-bar-stripes {
  0% {
    background-position-x: 1rem;
  }
}
:root {
  --referto-text-color: #e9a218;
  --referto-text-hover-color: #2c7fe7;
  --referto-literature-background-color: #318efd;
  --referto-title-background-color: #183153;
  --referto-content-text-color: #f1f1ef;
  --referfrom-text-shadow: rgba(35,35,35,0.5);
  --referfrom-text-color: #f1f1ef;
  --referfrom-text-hover-color: #f2b94b;
  --referfrom-link-color: #403e3b;
  --referfrom-link-hover-color: #235dac;
  --referfrom-background-color: #f1f1ef;
  --reference-anchor-color: #183153;
  --reference-anchor-up-color: #318efd;
}
[data-theme="dark"] {
  --referto-text-color: #f2b94b;
  --referto-text-hover-color: #2c7fe7;
  --referto-literature-background-color: #5c6167;
  --referto-title-background-color: #090a0b;
  --referto-content-text-color: #f1f1ef;
  --referfrom-text-shadow: rgba(35,35,35,0.5);
  --referfrom-text-color: #f1f1ef;
  --referfrom-text-hover-color: #f2b94b;
  --referfrom-link-color: #f1f1ef;
  --referfrom-link-hover-color: #f2b94b;
  --referfrom-background-color: rgba(92,97,103,0.68);
  --reference-anchor-color: #090a0b;
  --reference-anchor-up-color: #183153;
}
.hidden-anchor {
  position: relative;
  top: -150px;
  display: inline-block;
  height: 0;
  overflow: hidden;
}
.reference a {
  display: inline-block;
  color: var(--referto-text-color) !important;
  font-weight: bold;
  transition: all 0.2s ease-in-out;
}
.reference:hover a {
  transition: all 0.2s ease-in-out;
  text-decoration: none !important;
  color: var(--referto-text-hover-color) !important;
}
.reference:hover + .reference-bubble .reference-item {
  transform: translate(-40px, 10px) rotateX(0deg);
  transition: all 0.5s ease-in-out;
  opacity: 1;
}
.reference-bubble {
  display: inline-block;
}
.reference-item {
  transition: all 0.5s ease-in-out;
  opacity: 0;
  z-index: 99;
  display: flex;
  position: absolute;
  transform: translate(-40px, 10px) rotateX(90deg);
  width: auto;
  height: auto;
  clip-path: polygon(5px 10px, 20px 10px, 30px 0, 40px 10px, calc(100% - 5px) 10px, 100% 15px, 100% calc(100% - 5px), calc(100% - 5px) 100%, 5px 100%, 0 calc(100% - 5px), 0 15px, 5px 10px);
}
.reference-literature {
  max-width: 200px;
  padding: 20px 10px 10px 10px;
  background: var(--referto-literature-background-color);
  color: var(--referto-content-text-color) !important;
  word-wrap: break-word;
  word-break: break-all;
  display: flex;
  align-items: center;
}
.reference-title {
  padding: 20px 10px 10px 10px;
  background: var(--referto-title-background-color);
  color: var(--referto-content-text-color) !important;
  writing-mode: vertical-lr;
  display: flex;
  justify-content: center;
}
.reference-source {
  font-size: 16px;
  height: auto;
  line-height: 26px;
  width: fit-content;
  margin: 5px 0;
  max-width: 90%;
  background: var(--referfrom-background-color);
  box-shadow: 1px 1px 1px var(--referfrom-text-shadow);
  border-radius: 8px;
  padding-right: 10px;
}
.reference-source pangu {
  display: none;
}
a.reference-anchor {
  border-bottom-left-radius: 5px;
  border-top-left-radius: 5px;
  color: var(--referfrom-text-color) !important;
  background: var(--reference-anchor-color);
  height: 30px;
  display: inline-block;
  width: fit-content;
  padding: 0px 0px 0px 10px;
}
a.reference-anchor:hover {
  color: var(--referfrom-text-hover-color) !important;
  text-decoration: none !important;
}
a.reference-anchor:hover .reference-anchor-up {
  color: var(--referfrom-text-hover-color) !important;
}
a.reference-link {
  color: var(--referfrom-link-color) !important;
  padding: 0px 10px;
}
a.reference-link:hover {
  color: var(--referfrom-link-hover-color) !important;
  text-decoration: none !important;
}
.reference-anchor-up {
  color: var(--referfrom-text-color) !important;
  height: 30px;
  width: 40px;
  padding: 0px 0px 0px 10px;
  background: var(--reference-anchor-up-color);
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  clip-path: polygon(0 0, 10px 50%, 0 100%, 100% 100%, 100% 0);
}
.site-card-group {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  margin: -8px;
  align-items: stretch;
}
.site-card {
  margin: 8px;
  width: calc(100% / 4 - 16px);
  display: block;
  line-height: 1.4;
  height: 100%;
}
@media screen and (min-width: 2048px) {
  .site-card {
    width: calc(100% / 5 - 16px);
  }
}
@media screen and (max-width: 768px) {
  .site-card {
    width: calc(100% / 3 - 16px);
  }
}
@media screen and (max-width: 500px) {
  .site-card {
    width: calc(100% / 2 - 16px);
  }
}
.site-card .img {
  width: 100%;
  height: 120px;
  overflow: hidden;
  border-radius: 6px;
  box-shadow: 0 1px 2px 0px rgba(0,0,0,0.2);
  background: #f6f6f6;
}
@media screen and (max-width: 500px) {
  .site-card .img {
    height: 100px;
  }
}
.site-card .img img {
  width: 100%;
  height: 100%;
  pointer-events: none;
  transition: transform 2s ease;
  object-fit: cover;
}
.site-card .info {
  margin-top: 8px;
}
.site-card .info img {
  width: 32px;
  height: 32px;
  pointer-events: none;
  border-radius: 16px;
  float: left;
  margin-right: 8px;
  margin-top: 2px;
}
.site-card .info span {
  display: block;
}
.site-card .info .title {
  font-weight: 600;
  font-size: var(--global-font-size);
  color: #444;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
  -webkit-line-clamp: 1;
  transition: all 0.28s ease;
  -moz-transition: all 0.28s ease;
  -webkit-transition: all 0.28s ease;
  -o-transition: all 0.28s ease;
}
.site-card .info .desc {
  font-size: var(--global-font-size);
  word-wrap: break-word;
  line-height: 1.2;
  color: #888;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
  -webkit-line-clamp: 2;
}
.site-card .img {
  transition: all 0.28s ease;
  -moz-transition: all 0.28s ease;
  -webkit-transition: all 0.28s ease;
  -o-transition: all 0.28s ease;
}
.site-card:hover .img {
  box-shadow: 0 4px 8px 0px rgba(0,0,0,0.1), 0 2px 4px 0px rgba(0,0,0,0.1), 0 4px 8px 0px rgba(0,0,0,0.1), 0 8px 16px 0px rgba(0,0,0,0.1);
}
.site-card:hover .info .title {
  color: #ff5722;
}
p.p.subtitle {
