function changeSort(event){
  if (sortNow === event.currentTarget.dataset.sort) return;
  sortNow = event.currentTarget.dataset.sort
  localStorage.setItem("sortNow",sortNow)
  feedGeneration++;
  nextPagePromise = null;
  loadingMore = false;
